package de.cagalj.fahrtenapp;

import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.graphics.Color;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity {
 Db db; LinearLayout root,body; String screen="Startseite",filter="Monat",search=""; long customerId=-1,projectId=-1,editId=-1; boolean dark=false; long timerStart=0; static final int PDF=10,XLSX=11,BACKUP=12,RESTORE=13,LOGO=14; Uri logo; String selectedDay=today(); Calendar calendarMonth=Calendar.getInstance();
 int bg(){return dark?0xff101827:0xfff3f6fb;} int fg(){return dark?Color.WHITE:0xff152238;} int card(){return dark?0xff202c40:Color.WHITE;} int accent(){return 0xff1676c9;}
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new Db(this);android.content.SharedPreferences p=getPreferences(0);dark=p.getBoolean("dark",false);timerStart=p.getLong("timer",0);String l=p.getString("logo","");if(!l.isEmpty())logo=Uri.parse(l);show("Startseite");}
 static String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.GERMANY).format(new Date());} static String now(){return new SimpleDateFormat("HH:mm",Locale.GERMANY).format(new Date());} static String money(double n){return String.format(Locale.GERMANY,"%.2f",n);} static double num(String s){try{return Double.parseDouble(s.trim().replace(",","."));}catch(Exception e){return 0;}} static double hours(String a,String b,int pause){try{SimpleDateFormat f=new SimpleDateFormat("HH:mm",Locale.GERMANY);long d=f.parse(b).getTime()-f.parse(a).getTime();if(d<0)d+=86400000;return Math.max(0,d/3600000.0-pause/60.0);}catch(Exception e){return 0;}}
 TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(fg());t.setPadding(8,10,8,10);if(bold)t.setTypeface(null,1);return t;}
 LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 void addButton(LinearLayout parent,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(0xff172c44);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffa9def9));b.setOnClickListener(v->r.run());parent.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 void line(String s){body.addView(text(s,17,true));} void label(String s){body.addView(text(s,14,false));}
 void show(String name){screen=name;root=vertical();root.setBackgroundColor(bg());setContentView(root);LinearLayout top=vertical();top.setPadding(18,14,18,10);root.addView(top);TextView title=text("‹   "+name,23,true);title.setOnClickListener(v->show("Startseite"));top.addView(title);ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=vertical();body.setPadding(18,8,18,25);scroll.addView(body);if(logo!=null){try{android.graphics.drawable.Drawable d=android.graphics.drawable.Drawable.createFromStream(getContentResolver().openInputStream(logo),null);if(d!=null){d.setAlpha(28);body.setBackground(d);}}catch(Exception ignored){}}switch(name){case "Startseite":home();break;case "Übersicht":overview();break;case "Kalender":calendarScreen();break;case "Tageseinträge":dayScreen();break;case "Arbeitszeit / Fahrt":entries();break;case "Kunden":customers();break;case "Projekte":projects();break;case "Projektdetails":projectDetails();break;case "Eintrag":entryForm();break;case "Auswertung":stats();break;case "Einstellungen":settings();break;case "Firmendaten":company();break;}}
 void tile(String title,String value,int color){LinearLayout l=vertical();l.setPadding(18,14,18,14);android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable();g.setColor(color);g.setCornerRadius(22);l.setBackground(g);TextView t=text(title,13,false);t.setTextColor(Color.WHITE);l.addView(t);TextView v=text(value,23,true);v.setTextColor(Color.WHITE);l.addView(v);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(3,4,3,4);((LinearLayout)body.getChildAt(body.getChildCount()-1)).addView(l,lp);}
 void home(){label(new SimpleDateFormat("EEEE, dd. MMMM yyyy",Locale.GERMANY).format(new Date()));line("Projekt Erfassung");double[] s=totals("substr(e.day,1,7)=?",new String[]{today().substring(0,7)});LinearLayout r=new LinearLayout(this);body.addView(r);tile("MONATSVERDIENST",money(s[1])+" €",0xff137a88);tile("ARBEITSZEIT",money(s[0])+" h",0xff4265bd);r=new LinearLayout(this);body.addView(r);tile("KILOMETER",money(s[2])+" km",0xff9c59a6);tile("FAHRTVERGÜTUNG",money(s[4])+" €",0xffdf8b37);addButton(body,"📅 Kalender und Tagesverdienste",()->show("Kalender"));addButton(body,"＋ Arbeit / Fahrt erfassen",()->{editId=-1;show("Eintrag");});addButton(body,"📊 Auswertungen",()->show("Auswertung"));addButton(body,"🏗 Kunden und Projekte",()->show("Kunden"));addButton(body,"⚙ Einstellungen und Firmendaten",()->show("Einstellungen"));if(timerStart>0){label("Timer läuft seit "+new SimpleDateFormat("HH:mm",Locale.GERMANY).format(new Date(timerStart)));addButton(body,"■ Arbeitszeit stoppen",()->{String start=new SimpleDateFormat("HH:mm",Locale.GERMANY).format(new Date(timerStart));timerStart=0;getPreferences(0).edit().putLong("timer",0).apply();editId=-1;prefillStart=start;show("Eintrag");});}else addButton(body,"▶ Arbeitszeit starten",()->{timerStart=System.currentTimeMillis();getPreferences(0).edit().putLong("timer",timerStart).apply();show("Startseite");});}
 String prefillStart="";
 void periodButtons(){LinearLayout row=new LinearLayout(this);for(String s:new String[]{"Tag","Woche","Monat","Jahr"}){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setAllCaps(false);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(s.equals(filter)?0xff64c9df:0xffd6e6f5));row.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{filter=s;show(screen);});}body.addView(row);label("Zeitraum: "+filter);}
 String[] condition(){Calendar cal=Calendar.getInstance();cal.setFirstDayOfWeek(Calendar.MONDAY);String t=today();switch(filter){case "Tag":return new String[]{"e.day=?",t};case "Woche":cal.set(Calendar.DAY_OF_WEEK,Calendar.MONDAY);String weekStart=new SimpleDateFormat("yyyy-MM-dd",Locale.GERMANY).format(cal.getTime());cal.add(Calendar.DAY_OF_MONTH,6);return new String[]{"e.day>=? AND e.day<=?",weekStart,new SimpleDateFormat("yyyy-MM-dd",Locale.GERMANY).format(cal.getTime())};case "Jahr":return new String[]{"substr(e.day,1,4)=?",t.substring(0,4)};default:return new String[]{"substr(e.day,1,7)=?",t.substring(0,7)};}}
 double[] totals(String where,String[] args){double h=0,eu=0,km=0,rides=0,travelCost=0,workPay=0,extras=0;Cursor c=db.query("SELECT e.start,e.end,e.break_min,e.travel_out,e.travel_back,e.km,e.km_rate,e.extra,e.rate FROM entries e WHERE "+where,args);while(c.moveToNext()){double hrs=hours(c.getString(0),c.getString(1),c.getInt(2));double k=c.getDouble(5)*(c.getInt(3)+c.getInt(4));h+=hrs;km+=k;rides+=c.getInt(3)+c.getInt(4);workPay+=hrs*c.getDouble(8);travelCost+=k*c.getDouble(6);extras+=c.getDouble(7);eu+=hrs*c.getDouble(8)+k*c.getDouble(6)+c.getDouble(7);}c.close();return new double[]{h,eu,km,rides,travelCost,workPay,extras};}
 void overview(){addButton(body,"📅 Monatskalender öffnen",()->show("Kalender"));periodButtons();double[] t=totals(condition()[0],Arrays.copyOfRange(condition(),1,condition().length));summary(t);addButton(body,"+ Neuen Eintrag hinzufügen",()->{editId=-1;show("Eintrag");});addButton(body,"Kalenderansicht / Liste",()->show("Arbeitszeit / Fahrt"));listEntries();}

 void calendarScreen(){
  Calendar first=(Calendar)calendarMonth.clone();first.set(Calendar.DAY_OF_MONTH,1);
  SimpleDateFormat monthFmt=new SimpleDateFormat("MMMM yyyy",Locale.GERMANY);
  LinearLayout navigation=new LinearLayout(this);body.addView(navigation);
  for(int dir:new int[]{-1,0,1}){Button b=new Button(this);b.setAllCaps(false);b.setText(dir<0?"◀":dir>0?"▶":monthFmt.format(first.getTime()));navigation.addView(b,new LinearLayout.LayoutParams(0,-2,dir==0?3:1));b.setOnClickListener(v->{if(dir!=0)calendarMonth.add(Calendar.MONTH,dir);else calendarMonth.setTime(new Date());show("Kalender");});}
  String[] weekdays={"Mo","Di","Mi","Do","Fr","Sa","So"};LinearLayout heading=new LinearLayout(this);body.addView(heading);for(String w:weekdays){TextView t=text(w,13,true);t.setGravity(Gravity.CENTER);heading.addView(t,new LinearLayout.LayoutParams(0,-2,1));}
  Calendar cursor=(Calendar)first.clone();int offset=(cursor.get(Calendar.DAY_OF_WEEK)+5)%7;cursor.add(Calendar.DAY_OF_MONTH,-offset);
  SimpleDateFormat iso=new SimpleDateFormat("yyyy-MM-dd",Locale.GERMANY);
  for(int row=0;row<6;row++){LinearLayout week=new LinearLayout(this);body.addView(week);for(int col=0;col<7;col++){
   String day=iso.format(cursor.getTime());double[] sums=totals("e.day=?",new String[]{day});boolean current=cursor.get(Calendar.MONTH)==first.get(Calendar.MONTH);
   LinearLayout cell=vertical();cell.setPadding(2,4,2,4);android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(!current?(dark?0xff283140:0xffe6e9ef):sums[1]>0?(dark?0xff264b47:0xffb9eddb):(dark?0xff26344b:0xffe7f2ff));shape.setCornerRadius(15);cell.setBackground(shape);
   TextView number=text(""+cursor.get(Calendar.DAY_OF_MONTH),13,true);number.setGravity(Gravity.CENTER);cell.addView(number);
   TextView amount=text(sums[1]>0?String.format(Locale.GERMANY,"%.0f €",sums[1]):"",11,true);amount.setTextColor(dark?0xffa8f0ca:0xff167a52);amount.setGravity(Gravity.CENTER);cell.addView(amount);
   TextView hrs=text(sums[0]>0?money(sums[0])+" h":"",9,false);hrs.setGravity(Gravity.CENTER);cell.addView(hrs);
   LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,155,1);lp.setMargins(1,1,1,1);week.addView(cell,lp);cell.setOnClickListener(v->{selectedDay=day;show("Tageseinträge");});cursor.add(Calendar.DAY_OF_MONTH,1);
  }}
  addButton(body,"+ Eintrag für heute",()->{selectedDay=today();editId=-1;show("Eintrag");});
 }
 void dayScreen(){line("📅 "+selectedDay);double[] t=totals("e.day=?",new String[]{selectedDay});summary(t);addButton(body,"+ Eintrag an diesem Tag",()->{editId=-1;show("Eintrag");});
 Cursor c=db.query("SELECT e.id,c.name,p.name,e.start,e.end,e.break_min,e.travel_out,e.travel_back,e.km,e.km_rate,e.extra,e.rate FROM entries e JOIN projects p ON p.id=e.project_id JOIN customers c ON c.id=p.customer_id WHERE e.day=? ORDER BY e.start,e.id",selectedDay);int n=0;while(c.moveToNext()){n++;long id=c.getLong(0);double h=hours(c.getString(3),c.getString(4),c.getInt(5));double km=c.getDouble(8)*(c.getInt(6)+c.getInt(7));TextView item=text("🟦 "+c.getString(3)+"–"+c.getString(4)+" · "+c.getString(1)+" / "+c.getString(2)+"\n"+money(h)+" h · "+money(h*c.getDouble(11)+km*c.getDouble(9)+c.getDouble(10))+" €",15,true);item.setBackgroundColor(card());body.addView(item);item.setOnClickListener(v->new AlertDialog.Builder(this).setItems(new String[]{"Bearbeiten","Löschen"},(d,which)->{if(which==0){editId=id;show("Eintrag");}else confirmDelete("entries",id,"Tageseinträge");}).show());}c.close();if(n==0)label("Für diesen Tag sind noch keine Einträge vorhanden.");addButton(body,"← Zurück zum Kalender",()->show("Kalender"));
 }
 void entries(){periodButtons();String[] range=condition();summary(totals(range[0],Arrays.copyOfRange(range,1,range.length)));addButton(body,"+ Arbeitszeit / Fahrt erfassen",()->{editId=-1;show("Eintrag");});listEntries();}
 void listEntries(){String[] cond=condition();String sql="SELECT e.id,e.day,c.name,p.name,e.start,e.end,e.break_min,e.travel_out,e.travel_back,e.km,e.km_rate,e.extra,e.rate,e.status FROM entries e JOIN projects p ON p.id=e.project_id JOIN customers c ON c.id=p.customer_id WHERE "+cond[0]+" ORDER BY e.day DESC,e.id DESC";Cursor c=db.query(sql,Arrays.copyOfRange(cond,1,cond.length));int count=0;while(c.moveToNext()){count++;long id=c.getLong(0);double h=hours(c.getString(4),c.getString(5),c.getInt(6));double km=c.getDouble(9)*(c.getInt(7)+c.getInt(8));double earned=h*c.getDouble(12)+km*c.getDouble(10)+c.getDouble(11);String s=c.getString(1)+" · "+c.getString(2)+" / "+c.getString(3)+"\n"+c.getString(4)+"–"+c.getString(5)+" · "+money(h)+" h · "+money(km)+" km · "+money(earned)+" € · "+c.getString(13);TextView item=text(s,15,false);item.setBackgroundColor(card());body.addView(item);item.setOnClickListener(v->new AlertDialog.Builder(this).setItems(new String[]{"Bearbeiten","Löschen"},(d,which)->{if(which==0){editId=id;show("Eintrag");}else confirmDelete("entries",id,"Arbeitszeit / Fahrt");}).show());}c.close();if(count==0)label("Keine Einträge in diesem Zeitraum.");}
 void confirmDelete(String table,long id,String next){new AlertDialog.Builder(this).setMessage("Diesen Datensatz wirklich löschen?").setPositiveButton("Löschen",(d,w)->{db.delete(table,id);show(next);}).setNegativeButton("Abbrechen",null).show();}
 EditText input(LinearLayout p,String hint,String value){EditText e=new EditText(this);e.setSingleLine(true);e.setTextColor(fg());e.setHint(hint);e.setText(value==null?"":value);p.addView(e);return e;}
 void customers(){EditText q=input(body,"Kunden suchen",search);q.addTextChangedListener(watcher(s->{search=s;}));addButton(body,"+ Neuen Kunden anlegen",()->customerForm(-1,""));Cursor c=db.query("SELECT id,name FROM customers ORDER BY name");while(c.moveToNext()){long id=c.getLong(0);String name=c.getString(1);if(!name.toLowerCase().contains(search.toLowerCase()))continue;addButton(body,name,()->{customerId=id;show("Projekte");});}c.close();}
 interface Changed{void change(String s);}android.text.TextWatcher watcher(Changed change){return new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){change.change(s.toString());}public void afterTextChanged(android.text.Editable e){}};}
 void customerForm(long id,String name){EditText e=new EditText(this);e.setText(name);new AlertDialog.Builder(this).setTitle("Kunde").setView(e).setPositiveButton("Speichern",(d,w)->{String n=e.getText().toString().trim();if(n.isEmpty())return;android.content.ContentValues v=new android.content.ContentValues();v.put("name",n);if(id<0)db.insert("customers",v);else db.update("customers",id,v);show("Kunden");}).setNeutralButton(id<0?"Abbrechen":"Löschen",(d,w)->{if(id>=0){Cursor c=db.query("SELECT COUNT(*) FROM projects WHERE customer_id=?",""+id);c.moveToFirst();boolean used=c.getInt(0)>0;c.close();if(used)toast("Kunde hat noch Projekte");else{db.delete("customers",id);show("Kunden");}}}).show();}
 void projects(){line("Projekte des Kunden");addButton(body,"Kunde bearbeiten",()->{Cursor c=db.query("SELECT name FROM customers WHERE id=?",""+customerId);if(c.moveToFirst())customerForm(customerId,c.getString(0));c.close();});addButton(body,"+ Neues Projekt",()->{projectId=-1;show("Projektdetails");});Cursor c=db.query("SELECT id,name FROM projects WHERE customer_id=? ORDER BY name",""+customerId);while(c.moveToNext()){long id=c.getLong(0);String name=c.getString(1);addButton(body,name,()->{projectId=id;show("Projektdetails");});}c.close();}
 void projectDetails(){String[] cols={"name","address","km","work","rate","km_rate","contact","phone","number"};String[] labels={"Projektname","Adresse","Entfernung einfach (km)","Arbeiten / Tätigkeit","Stundensatz (€)","Kilometersatz (€/km)","Ansprechpartner","Telefonnummer","Projektnummer"};String[] values=new String[cols.length];Arrays.fill(values,"");values[5]="0,50";if(projectId>=0){Cursor c=db.query("SELECT "+String.join(",",cols)+" FROM projects WHERE id=?",""+projectId);if(c.moveToFirst())for(int i=0;i<cols.length;i++)values[i]=c.getString(i);c.close();}EditText[] fields=new EditText[cols.length];for(int i=0;i<cols.length;i++)if(i!=3)fields[i]=input(body,labels[i],values[i]);label("Tätigkeiten und Preise: Pro Zeile Tätigkeit | Stundensatz (z. B. Wartung | 85)");
 EditText workPrices=input(body,"Mehrere Tätigkeiten (eine pro Zeile)",values[3]);fields[3]=workPrices;
 addButton(body,"Route online prüfen (Google Maps)",()->{String origin=getSharedPreferences("company",0).getString("street","")+", "+getSharedPreferences("company",0).getString("city","");String dest=fields[1].getText().toString();if(origin.trim().equals(",")||dest.trim().isEmpty()){toast("Bitte Firmenadresse und Projektadresse eingeben");return;}try{String u="https://www.google.com/maps/dir/?api=1&origin="+java.net.URLEncoder.encode(origin,"UTF-8")+"&destination="+java.net.URLEncoder.encode(dest,"UTF-8")+"&travelmode=driving";startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));toast("Entfernung der gewünschten Route anschließend im Projekt eintragen");}catch(Exception ex){toast("Kartenansicht nicht verfügbar");}});addButton(body,"📍 Längste Google-Route automatisch übernehmen",()->fetchGoogleRoute(fields[1].getText().toString(),fields[2]));label("Für die automatische Übernahme benötigst du einen Google Routes API-Schlüssel mit aktivierter Abrechnung. Ohne Schlüssel kannst du die Strecke über Google Maps prüfen und manuell eintragen.");addButton(body,"Projekt speichern",()->{if(fields[0].getText().toString().trim().isEmpty()){toast("Projektname fehlt");return;}android.content.ContentValues v=new android.content.ContentValues();v.put("customer_id",customerId);for(int i=0;i<cols.length;i++){String s=fields[i].getText().toString();if(i==2||i==4||i==5)v.put(cols[i],num(s));else v.put(cols[i],s);}if(projectId<0)projectId=db.insert("projects",v);else db.update("projects",projectId,v);show("Projekte");});if(projectId>=0)addButton(body,"Projekt löschen",()->{Cursor c=db.query("SELECT COUNT(*) FROM entries WHERE project_id=?",""+projectId);c.moveToFirst();boolean used=c.getInt(0)>0;c.close();if(used)toast("Projekt enthält noch Einträge");else confirmDelete("projects",projectId,"Projekte");});}
 void entryForm(){ArrayList<Long> ids=new ArrayList<>();ArrayList<String> names=new ArrayList<>();Cursor pc=db.query("SELECT p.id,c.name,p.name FROM projects p JOIN customers c ON c.id=p.customer_id ORDER BY c.name,p.name");while(pc.moveToNext()){ids.add(pc.getLong(0));names.add(pc.getString(1)+" / "+pc.getString(2));}pc.close();if(ids.isEmpty()){label("Bitte zuerst einen Kunden und ein Projekt anlegen.");addButton(body,"Kunden anlegen",()->show("Kunden"));return;}
 String[] cols={"project_id","day","start","end","break_min","travel_out","travel_back","travel_minutes","extra","status","rate","km_rate","km","note"};String[] old=new String[cols.length];Arrays.fill(old,"");old[1]=selectedDay;old[2]=prefillStart.isEmpty()?now():prefillStart;old[3]=now();prefillStart="";old[5]="1";old[6]="1";old[9]="Offen";if(editId>=0){Cursor c=db.query("SELECT "+String.join(",",cols)+" FROM entries WHERE id=?",""+editId);if(c.moveToFirst())for(int i=0;i<cols.length;i++)old[i]=c.getString(i);c.close();}
 Spinner proj=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names);proj.setAdapter(adapter);body.addView(text("Kunde / Projekt",15,true));body.addView(proj);if(!old[0].isEmpty()){int ix=ids.indexOf((long)num(old[0]));if(ix>=0)proj.setSelection(ix);}
 ArrayList<String> tasks=new ArrayList<>();ArrayList<Double> taskRates=new ArrayList<>();
 Spinner taskPicker=new Spinner(this);body.addView(text("Tätigkeit / Preis",15,true));body.addView(taskPicker);
 Runnable loadTasks=()->{tasks.clear();taskRates.clear();long pid=ids.get(proj.getSelectedItemPosition());Cursor tc=db.query("SELECT work,rate FROM projects WHERE id=?",""+pid);if(tc.moveToFirst()){String raw=tc.getString(0);double base=tc.getDouble(1);if(raw!=null)for(String line:raw.split("\\n")){String[] parts=line.split("\\|");if(parts.length>=2){tasks.add(parts[0].trim()+" · "+money(num(parts[1]))+" €/h");taskRates.add(num(parts[1]));}}if(tasks.isEmpty()){tasks.add("Standard · "+money(base)+" €/h");taskRates.add(base);}}tc.close();taskPicker.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,tasks));};
 proj.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long id){loadTasks.run();}});loadTasks.run();
 EditText day=input(body,"Datum (JJJJ-MM-TT)",old[1]),start=input(body,"Beginn (HH:MM)",old[2]),end=input(body,"Ende (HH:MM)",old[3]),pause=input(body,"Pause in Minuten",old[4]),travel=input(body,"Fahrtzeit in Minuten (optional)",old[7]),extra=input(body,"Zusätzliche Kosten (€)",old[8]),note=input(body,"Notiz",old[13]);
 CheckBox out=new CheckBox(this),back=new CheckBox(this);out.setText("Hinfahrt");back.setText("Rückfahrt");out.setChecked("1".equals(old[5]));back.setChecked("1".equals(old[6]));body.addView(out);body.addView(back);
 Spinner status=new Spinner(this);String[] statuses={"Offen","Abgerechnet","Bezahlt"};status.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,statuses));body.addView(text("Abrechnungsstatus",15,true));body.addView(status);for(int i=0;i<3;i++)if(statuses[i].equals(old[9]))status.setSelection(i);
 addButton(body,"Eintrag speichern",()->{String d=day.getText().toString().trim(),a=start.getText().toString().trim(),b=end.getText().toString().trim();if(!d.matches("\\d{4}-\\d{2}-\\d{2}")||!a.matches("([01]\\d|2[0-3]):[0-5]\\d")||!b.matches("([01]\\d|2[0-3]):[0-5]\\d")){toast("Datum oder Uhrzeit ungültig");return;}try{SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd",Locale.GERMANY);f.setLenient(false);f.parse(d);}catch(Exception ex){toast("Datum ungültig");return;}long pid=ids.get(proj.getSelectedItemPosition());double rate=0,kmRate=0,km=0;Cursor c=db.query("SELECT rate,km_rate,km FROM projects WHERE id=?",""+pid);if(c.moveToFirst()){rate=c.getDouble(0);kmRate=c.getDouble(1);km=c.getDouble(2);}c.close();if(editId>=0){Cursor previous=db.query("SELECT project_id,rate,km_rate,km FROM entries WHERE id=?",""+editId);if(previous.moveToFirst()&&previous.getLong(0)==pid){rate=previous.getDouble(1);kmRate=previous.getDouble(2);km=previous.getDouble(3);}previous.close();}
 android.content.ContentValues v=new android.content.ContentValues();v.put("project_id",pid);v.put("day",d);v.put("start",a);v.put("end",b);v.put("break_min",(int)num(pause.getText().toString()));v.put("travel_out",out.isChecked()?1:0);v.put("travel_back",back.isChecked()?1:0);v.put("travel_minutes",(int)num(travel.getText().toString()));v.put("extra",num(extra.getText().toString()));v.put("status",statuses[status.getSelectedItemPosition()]);if(editId<0 && !taskRates.isEmpty())rate=taskRates.get(taskPicker.getSelectedItemPosition());v.put("rate",rate);v.put("km_rate",kmRate);v.put("km",km);v.put("note",note.getText().toString());if(editId<0)db.insert("entries",v);else db.update("entries",editId,v);editId=-1;show("Tageseinträge");});}
 void stats(){periodButtons();String[] c=condition();double[] t=totals(c[0],Arrays.copyOfRange(c,1,c.length));line("Einnahmen: "+money(t[1])+" €");label("Arbeitszeit "+money(t[0])+" h · Fahrstrecke "+money(t[2])+" km");line("Einnahmen und erfasste Zusatzkosten");body.addView(new BarsView(new double[]{t[1],t[6]},new String[]{"Einnahmen","Zusatzkosten"},new int[]{0xff16a085,0xffed8750}),new LinearLayout.LayoutParams(-1,240));label("Hinweis: 'Zusätzliche Kosten' sind im bisherigen Datenmodell Teil der Vergütung, keine separat gebuchten Betriebsausgaben.");line("Vergleich zum Vorzeitraum");Calendar nowCal=Calendar.getInstance();Calendar prev=(Calendar)nowCal.clone();int unit=filter.equals("Tag")?Calendar.DAY_OF_YEAR:filter.equals("Woche")?Calendar.WEEK_OF_YEAR:filter.equals("Jahr")?Calendar.YEAR:Calendar.MONTH;prev.add(unit,-1);String start,end;SimpleDateFormat fmt=new SimpleDateFormat("yyyy-MM-dd",Locale.GERMANY);if(filter.equals("Tag")){start=end=fmt.format(prev.getTime());}else if(filter.equals("Woche")){prev.setFirstDayOfWeek(Calendar.MONDAY);prev.set(Calendar.DAY_OF_WEEK,Calendar.MONDAY);start=fmt.format(prev.getTime());prev.add(Calendar.DAY_OF_MONTH,6);end=fmt.format(prev.getTime());}else if(filter.equals("Monat")){prev.set(Calendar.DAY_OF_MONTH,1);start=fmt.format(prev.getTime());prev.set(Calendar.DAY_OF_MONTH,prev.getActualMaximum(Calendar.DAY_OF_MONTH));end=fmt.format(prev.getTime());}else{prev.set(Calendar.DAY_OF_YEAR,1);start=fmt.format(prev.getTime());prev.set(Calendar.DAY_OF_YEAR,prev.getActualMaximum(Calendar.DAY_OF_YEAR));end=fmt.format(prev.getTime());}double[] old=totals("e.day>=? AND e.day<=?",new String[]{start,end});body.addView(new BarsView(new double[]{old[1],t[1]},new String[]{"Vorperiode","Aktuell"},new int[]{0xff8a9fb8,0xff297cd4}),new LinearLayout.LayoutParams(-1,230));line("Letzte 12 Monate bis heute");double[] series=new double[12];String[] months=new String[12];Calendar m=Calendar.getInstance();m.add(Calendar.MONTH,-11);for(int i=0;i<12;i++){String key=new SimpleDateFormat("yyyy-MM",Locale.GERMANY).format(m.getTime());series[i]=totals("substr(e.day,1,7)=? AND e.day<=?",new String[]{key,today()})[1];months[i]=new SimpleDateFormat("MM/yy",Locale.GERMANY).format(m.getTime());m.add(Calendar.MONTH,1);}body.addView(new BarsView(series,months,null),new LinearLayout.LayoutParams(-1,270));addButton(body,"PDF exportieren",()->create(PDF,"application/pdf","CAGALJ-Arbeitsnachweis.pdf"));addButton(body,"Excel (.xlsx) exportieren",()->create(XLSX,"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","CAGALJ-Arbeitsnachweis.xlsx"));}
 class BarsView extends View{double[] vals;String[] names;int[] colors;android.graphics.Paint paint=new android.graphics.Paint(3);BarsView(double[] v,String[] n,int[] c){super(MainActivity.this);vals=v;names=n;colors=c;setBackgroundColor(card());}protected void onDraw(android.graphics.Canvas canvas){super.onDraw(canvas);float w=getWidth(),h=getHeight();float pad=34,base=h-52;double max=1;for(double v:vals)max=Math.max(max,v);float step=(w-pad*2)/vals.length;paint.setTextSize(vals.length>6?22:29);paint.setTextAlign(android.graphics.Paint.Align.CENTER);for(int i=0;i<vals.length;i++){float x=pad+step*(i+.5f);float height=(float)(Math.max(0,vals[i])/max*(h-108));paint.setColor(colors==null?0xff2d8ed0:colors[i%colors.length]);canvas.drawRoundRect(x-step*.32f,base-height,x+step*.32f,base,8,8,paint);paint.setColor(fg());paint.setTextSize(vals.length>6?18:26);canvas.drawText(names[i],x,h-19,paint);if(vals.length<=6){paint.setTextSize(24);canvas.drawText(String.format(Locale.GERMANY,"%.0f €",vals[i]),x,Math.max(26,base-height-8),paint);}}}}
 void fetchGoogleRoute(String destination,EditText kmField){android.content.SharedPreferences prefs=getSharedPreferences("company",0);String key=prefs.getString("maps_key","").trim();String origin=prefs.getString("street","")+", "+prefs.getString("city","");if(key.isEmpty()){toast("Bitte zuerst in Firmendaten den Google Routes API-Schlüssel eintragen");return;}if(destination.trim().isEmpty()||origin.trim().equals(",")){toast("Firmen- und Projektadresse erforderlich");return;}toast("Routen werden geprüft …");new Thread(()->{try{java.net.HttpURLConnection connection=(java.net.HttpURLConnection)new java.net.URL("https://routes.googleapis.com/directions/v2:computeRoutes").openConnection();connection.setRequestMethod("POST");connection.setConnectTimeout(12000);connection.setReadTimeout(16000);connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");connection.setRequestProperty("X-Goog-Api-Key",key);connection.setRequestProperty("X-Goog-FieldMask","routes.distanceMeters,routes.description");JSONObject request=new JSONObject();request.put("origin",new JSONObject().put("address",origin));request.put("destination",new JSONObject().put("address",destination));request.put("travelMode","DRIVE");request.put("computeAlternativeRoutes",true);try(java.io.OutputStream os=connection.getOutputStream()){os.write(request.toString().getBytes("UTF-8"));}int status=connection.getResponseCode();java.io.InputStream stream=status<300?connection.getInputStream():connection.getErrorStream();java.io.ByteArrayOutputStream buffer=new java.io.ByteArrayOutputStream();byte[] bytes=new byte[4096];int n;while((n=stream.read(bytes))!=-1)buffer.write(bytes,0,n);JSONObject result=new JSONObject(buffer.toString("UTF-8"));if(status>=300)throw new Exception(result.optJSONObject("error")!=null?result.getJSONObject("error").optString("message"):"HTTP "+status);JSONArray routes=result.optJSONArray("routes");if(routes==null||routes.length()==0)throw new Exception("Keine Route gefunden");int longest=0;for(int i=0;i<routes.length();i++)longest=Math.max(longest,routes.getJSONObject(i).optInt("distanceMeters"));double km=Math.round(longest/100.0)/10.0;runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Längste angebotene Route").setMessage("Google Routes liefert "+routes.length()+" Route(n). Längste: "+money(km)+" km (einfach). Übernehmen?").setNegativeButton("Abbrechen",null).setPositiveButton("Übernehmen",(d,w)->kmField.setText(money(km))).show());}catch(Exception ex){runOnUiThread(()->toast("Routenprüfung: "+ex.getMessage()));}}).start();}
 void company(){android.content.SharedPreferences pref=getSharedPreferences("company",0);line("Meine Firma / Ausgangsadresse");EditText name=input(body,"Firmenname",pref.getString("name",""));EditText street=input(body,"Straße und Hausnummer",pref.getString("street",""));EditText zip=input(body,"PLZ und Ort",pref.getString("city",""));EditText phone=input(body,"Telefon / E-Mail",pref.getString("contact",""));EditText apiKey=input(body,"Google Routes API-Schlüssel (optional)",pref.getString("maps_key",""));addButton(body,"Firmendaten speichern",()->{pref.edit().putString("name",name.getText().toString()).putString("street",street.getText().toString()).putString("city",zip.getText().toString()).putString("contact",phone.getText().toString()).putString("maps_key",apiKey.getText().toString()).apply();toast("Firmendaten gespeichert");show("Startseite");});label("Die Adresse dient als Ausgangspunkt für die Routenprüfung.");}
 void summary(double[] t){line("Arbeitsstunden: "+money(t[0])+" h  ·  Arbeitsverdienst: "+money(t[5])+" €");line("Fahrten (einzelne Strecken): "+(int)t[3]+"  ·  Kilometer: "+money(t[2])+" km");line("Fahrtkosten: "+money(t[4])+" €  ·  Weitere Kosten: "+money(t[6])+" €");TextView total=text("GESAMTVERDIENST: "+money(t[1])+" €",22,true);total.setTextColor(accent());total.setBackgroundColor(card());body.addView(total);}
 void settings(){addButton(body,"Firmendaten bearbeiten",()->show("Firmendaten"));addButton(body,"Design wechseln: "+(dark?"Dunkel":"Hell"),()->{dark=!dark;getPreferences(0).edit().putBoolean("dark",dark).apply();show("Einstellungen");});addButton(body,"Eigenes Logo auswählen",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,LOGO);});addButton(body,"Datensicherung erstellen (JSON)",()->create(BACKUP,"application/json","CAGALJ-Sicherung.json"));addButton(body,"Datensicherung wiederherstellen",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,RESTORE);});label("Achtung: Eine Wiederherstellung ersetzt alle vorhandenen Kunden, Projekte und Einträge. Sichere deine Daten vorher.");addButton(body,"PDF exportieren",()->create(PDF,"application/pdf","CAGALJ-Arbeitsnachweis.pdf"));addButton(body,"Excel exportieren",()->create(XLSX,"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","CAGALJ-Arbeitsnachweis.xlsx"));}
 void create(int code,String type,String filename){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(type).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(i,code);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{if(request==PDF)Exports.pdf(this,db,uri);else if(request==XLSX)Exports.xlsx(this,db,uri);else if(request==BACKUP){try(java.io.OutputStream o=getContentResolver().openOutputStream(uri)){o.write(db.backup().toString(2).getBytes("UTF-8"));}}else if(request==RESTORE){new AlertDialog.Builder(this).setTitle("Daten ersetzen?").setMessage("Alle aktuellen Einträge, Kunden und Projekte werden durch die Sicherung ersetzt.").setNegativeButton("Abbrechen",null).setPositiveButton("Wiederherstellen",(d,w)->{try(java.io.InputStream in=getContentResolver().openInputStream(uri)){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);db.restore(new JSONArray(out.toString("UTF-8")));toast("Wiederhergestellt");show("Startseite");}catch(Exception ex){toast("Importfehler: "+ex.getMessage());}}).show();return;}else if(request==LOGO){getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);logo=uri;getPreferences(0).edit().putString("logo",uri.toString()).apply();show("Startseite");return;}toast("Datei gespeichert");}catch(Exception ex){toast("Fehler: "+ex.getMessage());}}
}
